patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..45b2b99
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,17 @@
+"use strict";
+const eslintPath = process.env.ESLINT_PATH || "../lib/api";
+const { Linter } = require(eslintPath);
+console.log(`eslint ${require(eslintPath).Linter.version}`);
+const linter = new Linter({ configType: "flat" });
+const config = [{ languageOptions: { ecmaVersion: "latest", sourceType: "module" }, rules: { "no-var": ["error"] } }];
+const cases = {
+	"report (export function)": "export function a() {\n    console.log(o);\n    var o;\n    return o;\n}",
+	"no export": "function a() {\n    console.log(o);\n    var o;\n    return o;\n}",
+};
+let bug = false;
+for (const [name, code] of Object.entries(cases)) {
+	const r = linter.verifyAndFix(code, config);
+	console.log(`--- ${name}: fixed=${r.fixed}\n${r.output}`);
+	if (r.fixed && /console\.log\(o\);\s*let o;/u.test(r.output)) bug = true;
+}
+console.log(bug ? "\nBUG REPRODUCED: `let o` left after its use -> ReferenceError (TDZ)" : "\nnot reproduced");
